import type { Flashcard } from "./flashcardsData";

export const flashcardsLote4: Flashcard[] = [

  // ════════════════════════════════════════════════════════════════
  // PSIQUIATRIA — de 7 para ~70 (+63)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-psiq-001", front: "Quais são os critérios diagnósticos do DSM-5-TR para Transtorno Depressivo Maior (TDM)?", back: "Cinco ou mais dos seguintes sintomas por ≥ 2 semanas, com pelo menos um sendo (1) ou (2):\n1. Humor deprimido na maioria dos dias\n2. Anedonia (perda de interesse/prazer)\n3. Alteração de peso/apetite (>5%/mês)\n4. Insônia ou hipersonia\n5. Agitação ou retardo psicomotor\n6. Fadiga ou perda de energia\n7. Sentimentos de desvalia ou culpa excessiva\n8. Dificuldade de concentração ou tomada de decisão\n9. Pensamentos de morte ou ideação suicida\nCausam sofrimento clinicamente significativo ou prejuízo funcional.", category: "psiquiatria", tags: ["depressão", "dsm5", "diagnóstico"] },
  { id: "fc-psiq-002", front: "Qual a diferença entre Transtorno Bipolar I e II?", back: "**Bipolar I:** ≥ 1 episódio maníaco (≥7 dias, hospitalização, ou sintomas psicóticos) — episódios depressivos comuns mas não obrigatórios.\n**Bipolar II:** ≥ 1 episódio hipomaníaco (≥4 dias, sem hospitalização ou psicose) + ≥ 1 episódio depressivo maior — NUNCA episódio maníaco completo.\nMnemônico: Bipolar I = Internação; Bipolar II = Hipo (menor intensidade).", category: "psiquiatria", tags: ["bipolar", "mania", "hipomania"] },
  { id: "fc-psiq-003", front: "Quais os critérios para Síndrome de Abstinência Alcoólica grave e quando tratar na UTI?", back: "Abstinência grave: CIWA-Ar > 15 pontos.\nCaracterísticas: tremor intenso, diaforese, taquicardia, HAS, alucinações, convulsões, delirium tremens.\nDelirium tremens: 48-96h após última dose — confusão + hiperautonomia + mortalidade até 5% com tratamento.\nTratamento: diazepam IV titulado (sem teto) + tiamina 500mg IV ANTES de glicose + hidratação + monitorização contínua + UTI se CIWA > 15.", category: "psiquiatria", tags: ["abstinência", "álcool", "delirium tremens", "ciwa"] },
  { id: "fc-psiq-004", front: "Quais são os antipsicóticos de escolha na esquizofrenia e quando preferir cada um?", back: "**1ª geração (típicos):** haloperidol, clorpromazina — eficazes em sintomas positivos, mais efeitos extrapiramidais e tardivos.\n**2ª geração (atípicos):** risperidona, olanzapina, quetiapina, clozapina, aripiprazol — menores efeitos extrapiramidais, mais síndrome metabólica.\n**Clozapina:** única eficaz em esquizofrenia refratária (falha de ≥2 antipsicóticos) — monitorar agranulocitose (hemograma semanal).\nPrincípio: atípicos como 1ª escolha; clozapina para refratariedade.", category: "psiquiatria", tags: ["esquizofrenia", "antipsicótico", "clozapina"] },
  { id: "fc-psiq-005", front: "Quais os critérios diagnósticos do TOC e como diferenciar de TOC-like?", back: "TOC (DSM-5): obsessões (pensamentos intrusivos, persistentes, indesejados) + compulsões (comportamentos repetitivos para reduzir ansiedade), consumindo > 1h/dia e causando sofrimento/prejuízo.\nDiferenciais:\n- TOC × Transtorno de Personalidade Obsessivo-Compulsivo: no TPOC não há obsessões/compulsões egodistônicas\n- TOC × TAS (Transtorno de Acumulação): sem obsessões típicas\n- TOC × Psicose: insight preservado no TOC\nTratamento: ISRS (fluoxetina, sertralina, fluvoxamina) + TCC (exposição e prevenção de resposta).", category: "psiquiatria", tags: ["toc", "obsessivo", "compulsivo"] },
  { id: "fc-psiq-006", front: "Como manejar uma crise de agitação psicomotora na emergência?", back: "Abordagem escalonada:\n1. Verbal: ambiente calmo, 1 interlocutor, oferecer opções\n2. Farmacológica VO/SL: lorazepam 2mg OU olanzapina 10mg SL\n3. IM (se recusa VO): midazolam 5mg + haloperidol 5mg (sinergia) OU droperidol 5mg\n4. IV (internação): diazepam 10mg IV lento + haloperidol 5mg IV\nContraindicações: não usar haloperidol em suspeita de intoxicação por cocaína (rebaixar com BZD). ECG antes se QTc suspeito.", category: "psiquiatria", tags: ["agitação", "emergência", "contenção"] },
  { id: "fc-psiq-007", front: "Quais são os critérios para internação psiquiátrica involuntária no Brasil?", back: "Lei 10.216/2001: internação involuntária quando o paciente recusa E há:\n- Risco iminente de vida (própria ou de terceiros)\n- Grave sofrimento e incapacidade de autocuidado\nDocumentação: médico assina laudo → comunicar ao MP em 72h.\nInternação compulsória: ordenada por juiz.\nDireitos: comunicação familiar, informação sobre diagnóstico/tratamento, alta a qualquer momento se sem risco.", category: "psiquiatria", tags: ["internação", "lei 10216", "involuntária"] },
  { id: "fc-psiq-008", front: "Quais as fases do tratamento da depressão maior e metas de cada fase?", back: "**Fase aguda (0-3 meses):** meta = remissão (ausência de sintomas). Antidepressivo + psicoterapia. Avaliação em 2-4 semanas.\n**Fase de continuação (4-9 meses):** meta = consolidar remissão, prevenir recaída. Manter dose plena.\n**Fase de manutenção (>9 meses):** meta = prevenir recorrência. Indicada se ≥3 episódios, episódio grave ou crônico, suicidalidade.\n**NUNCA suspender abruptamente ISRS** — síndrome de descontinuação (FINISH: Flu-like, Insônia, Náusea, Imbalance, Sensações, Hiperativação).", category: "psiquiatria", tags: ["depressão", "tratamento", "antidepressivo"] },
  { id: "fc-psiq-009", front: "O que é síndrome serotoninérgica e como distinguir de síndrome neuroléptica maligna?", back: "**Síndrome Serotoninérgica:** tríade = alteração mental + hiperatividade autonômica + anormalidades neuromusculares (mioclonia, hiperreflexia, clonus). Início em horas após serotonérgico. Tratamento: suspender agente + ciproeptadina 8-12mg + BZD.\n**SNM:** rigidez em chumbo + hipertermia + instabilidade autonômica + CPK muito elevada. Início gradual (dias-semanas) após antipsicótico. Tratamento: suspender antipsicótico + dantrolene + bromocriptina + suporte.\nDiferença-chave: SS = hiperreflexia/clonus; SNM = rigidez em chumbo.", category: "psiquiatria", tags: ["serotonina", "neuroléptico", "emergência"] },
  { id: "fc-psiq-010", front: "Quais são os transtornos de ansiedade mais prevalentes e suas características distintas?", back: "**TAG:** preocupação excessiva e incontrolável com múltiplos temas por ≥6 meses + 3 sintomas somáticos.\n**Transtorno do Pânico:** ataques de pânico recorrentes + medo persistente de novos ataques.\n**Fobia Social (TAS):** medo de julgamento/humilhação em situações sociais.\n**Fobia Específica:** medo circunscrito a objeto/situação específica.\n**TEPT:** exposição a trauma → revivência + evitação + hiperativação + cognições negativas.\n**TOC:** obsessões + compulsões (tecnicamente não é transtorno de ansiedade no DSM-5 mas em capítulo próprio).", category: "psiquiatria", tags: ["ansiedade", "tag", "pânico", "fobia"] },
  { id: "fc-psiq-011", front: "Como avaliar risco suicida na emergência usando a Escala Columbia (C-SSRS)?", back: "C-SSRS avalia ideação (1-5) e comportamento:\n**Ideação 1-2:** passiva (desejo de morte, sem plano) → risco baixo\n**Ideação 3-4:** ativa sem plano definido/intenção → risco moderado\n**Ideação 5:** plano + intenção → risco ALTO\n**Comportamento:** tentativa prévia é o maior preditor de nova tentativa.\nConduta:\n- Baixo: alta com seguimento em 24-48h + plano de segurança\n- Moderado: avaliação psiquiátrica no PS\n- Alto: internação (voluntária ou involuntária)", category: "psiquiatria", tags: ["suicídio", "columbia", "c-ssrs", "risco"] },
  { id: "fc-psiq-012", front: "Quais as contraindicações absolutas dos ISRS e interações medicamentosas críticas?", back: "**Contraindicações absolutas:** uso concomitante de IMAO (síndrome serotoninérgica potencialmente fatal — washout: 14 dias para ISRS, 5 semanas para fluoxetina antes de IMAO).\n**Interações críticas:**\n- Tramadol: síndrome serotoninérgica\n- Linezolida: IMAO fraco → síndrome serotoninérgica\n- Tamoxifeno + paroxetina/fluoxetina: inibição CYP2D6 → redução de eficácia do tamoxifeno\n- AAS/AINEs: risco hemorrágico aumentado (plaquetopenia funcional)\n- Varfarina: monitorar INR\n**Síndrome de descontinuação:** FINISH — não suspender abruptamente.", category: "psiquiatria", tags: ["isrs", "interações", "imao", "contraindicações"] },
  { id: "fc-psiq-013", front: "Quais são os sintomas positivos e negativos da esquizofrenia e como isso impacta o tratamento?", back: "**Sintomas positivos** (excesso de função):\n- Alucinações (auditivas mais comuns — 'vozes')\n- Delírios (persecutórios, grandiosidade, referência)\n- Pensamento desorganizado, comportamento bizarro\n→ Respondem bem a antipsicóticos (típicos e atípicos)\n\n**Sintomas negativos** (déficit de função):\n- Afeto embotado, alogia, avolição, anedonia, associalidade\n→ Respondem mal a típicos; atípicos ligeiramente melhores; clozapina superior\n→ Maior impacto funcional a longo prazo.", category: "psiquiatria", tags: ["esquizofrenia", "positivos", "negativos"] },
  { id: "fc-psiq-014", front: "Como usar o lítio com segurança e quais os sinais de toxicidade?", back: "**Janela terapêutica estreita:** 0,6-1,2 mEq/L (manutenção); 0,8-1,0 mEq/L (profilaxia).\n**Monitoramento:** litemia 5-7 dias após ajuste, depois a cada 3-6 meses + creatinina + TSH + ECG.\n**Toxicidade leve (1,5-2 mEq/L):** tremor grosseiro, náuseas, diarreia, fraqueza.\n**Toxicidade moderada (2-2,5):** confusão, ataxia, disartria, nistagmo.\n**Toxicidade grave (>2,5):** convulsão, coma, arritmia → HEMODIÁLISE.\n**Atenção:** AINEs, IECA, diuréticos tiazídicos → aumentam litemia.", category: "psiquiatria", tags: ["lítio", "toxicidade", "monitoramento"] },
  { id: "fc-psiq-015", front: "Quais são os critérios diagnósticos do TDAH em adultos?", back: "DSM-5: ≥5 sintomas de desatenção E/OU ≥5 de hiperatividade/impulsividade (em adultos; crianças = 6), presentes por ≥6 meses, início antes dos 12 anos, em ≥2 contextos, causando prejuízo funcional.\n**Apresentações:** desatenta predominante, hiperativa-impulsiva predominante, combinada.\n**Tratamento adultos:** metilfenidato (1ª linha) → anfetaminas → atomoxetina → bupropiona.\n**Diagnósticos diferenciais:** TAG, depressão, bipolar, abuso de substâncias, apneia do sono, hipotireoidismo.", category: "psiquiatria", tags: ["tdah", "adultos", "metilfenidato"] },

  // ════════════════════════════════════════════════════════════════
  // GASTROENTEROLOGIA — de 8 para ~70 (+62)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-gastro-001", front: "Quais são os critérios de Roma IV para Síndrome do Intestino Irritável (SII)?", back: "Dor abdominal recorrente ≥1 dia/semana nos últimos 3 meses (com início ≥6 meses antes), associada a ≥2 dos:\n1. Relacionada à defecação\n2. Associada a mudança na frequência das fezes\n3. Associada a mudança no aspecto das fezes\n**Subtipos:** SII-D (diarréica), SII-C (constipação), SII-M (mista), SII-U (indefinida).\n**Red flags (excluir doença orgânica):** sangramento retal, perda de peso, febre, anemia, início após 50 anos, história familiar de CCR.", category: "gastroenterologia", tags: ["sii", "roma iv", "intestino irritável"] },
  { id: "fc-gastro-002", front: "Como estadiar a cirrose hepática e qual a sobrevida esperada?", back: "**Child-Pugh (A/B/C):** bilirrubina, albumina, INR, ascite, encefalopatia. A=5-6 pts, B=7-9, C=10-15.\n**MELD-Na:** melhor preditor de mortalidade em 90 dias; determina prioridade em lista de transplante.\n**Sobrevida mediana:** Child A ~15-20 anos; Child B ~5 anos; Child C ~1-2 anos.\n**Descompensação:** ascite, sangramento varicoso, PBE, encefalopatia hepática → indica Child B/C e piora prognóstico.\n**Transplante:** indicado com MELD ≥15 ou complicações graves.", category: "gastroenterologia", tags: ["cirrose", "child-pugh", "meld", "transplante"] },
  { id: "fc-gastro-003", front: "Qual a abordagem da hemorragia digestiva alta (HDA) não varicosa?", back: "**Escore de Glasgow-Blatchford:** estratifica risco pré-endoscopia (0 = alta segura).\n**Escore Rockall:** estratifica risco pós-endoscopia.\nManejo:\n1. Estabilização hemodinâmica: acesso IV + SF 0,9% + transfusão se Hb <7 (ou <8 em cardiopatas)\n2. IBP: pantoprazol 80mg IV bolus → 8mg/h BIC (reduz ressangramento em úlcera com estigmas)\n3. Endoscopia em < 24h (< 12h se instável)\n4. Tratamento endoscópico: hemoclipe + adrenalina em úlcera com sangramento ativo\n**Helicobacter pylori:** erradicar se positivo — reduz recorrência.", category: "gastroenterologia", tags: ["hda", "úlcera", "endoscopia", "ibp"] },
  { id: "fc-gastro-004", front: "Quais são os critérios diagnósticos e o manejo da Peritonite Bacteriana Espontânea (PBE)?", back: "**Diagnóstico:** PMN ≥ 250 cel/mm³ no líquido ascítico (independente de cultura).\n**Tratamento:** cefotaxima 2g IV 8/8h por 5 dias.\n**Prevenção de Síndrome Hepatorrenal:** albumina 1,5g/kg no D1 + 1g/kg no D3 (reduz SHR de 33% para 10%).\n**Profilaxia secundária:** norfloxacina 400mg/dia VO indefinidamente após 1º episódio.\n**Profilaxia primária:** indicada com ascite + proteína ascítica < 1,5g/dL + Child C ou bilirrubina > 3mg/dL → norfloxacina 400mg/dia.", category: "gastroenterologia", tags: ["pbe", "ascite", "cirrose", "albumina"] },
  { id: "fc-gastro-005", front: "Como diferenciar e manejar Doença de Crohn vs Retocolite Ulcerativa?", back: "**Doença de Crohn:** qualquer segmento do TGI (boca ao ânus), transmural, granulomas, skip lesions, fístulas/abscessos possíveis, sem cura cirúrgica.\n**RCU:** apenas cólon e reto, mucosa superficial, sem granulomas, contínua do reto, sangramento frequente, colectomia total = curativa.\n**Tratamento leve-moderado:** mesalazina (RCU >> Crohn), corticoide (indução).\n**Moderado-grave:** azatioprina/6-MP (manutenção), infliximabe/adalimumabe (anti-TNF), vedolizumabe, ustekinumabe.\n**Emergência:** megacólon tóxico → colectomia urgente.", category: "gastroenterologia", tags: ["crohn", "rcu", "dii", "biológico"] },
  { id: "fc-gastro-006", front: "Quais são os critérios diagnósticos e classificação de gravidade da pancreatite aguda?", back: "**Diagnóstico:** ≥2 de: (1) dor abdominal típica; (2) amilase/lipase >3× LSN; (3) TC com pancreatite.\n**Gravidade (revisão Atlanta 2012):**\n- Leve: sem falência orgânica, sem complicações locais\n- Moderada: falência orgânica transitória (<48h) ou complicações locais\n- Grave: falência orgânica persistente (>48h)\n**Score BISAP ≥3:** mortalidade >5%.\n**Manejo:** Ringer Lactato 250-500mL/h (superior ao SF), analgesia, dieta oral precoce (24-48h se leve), jejum só se vômitos intratáveis, ATB SOMENTE em necrose infectada.", category: "gastroenterologia", tags: ["pancreatite", "atlanta", "bisap", "rl"] },
  { id: "fc-gastro-007", front: "Quais são os critérios para triagem e vigilância do hepatocarcinoma (CHC) em cirróticos?", back: "**Quem vigiar:** cirróticos Child A/B + todos hepatite B (mesmo sem cirrose se HBsAg+ com carga viral detectável ou história familiar).\n**Como:** Ultrassom a cada 6 meses ± AFP.\n**Diagnóstico:** nódulo > 1cm em cirrótico com captação arterial + washout na TC/RM = diagnóstico sem biópsia.\n**Estadiamento BCLC:** determina tratamento (ablação, ressecção, TACE, sorafenibe, transplante).\n**Transplante:** critérios de Milão (1 nódulo <5cm OU 3 nódulos <3cm, sem invasão vascular).", category: "gastroenterologia", tags: ["hepatocarcinoma", "chc", "bclc", "vigilância"] },
  { id: "fc-gastro-008", front: "Quais são as indicações de colonoscopia e intervalo de vigilância para pólipo colorretal?", back: "**Indicações:** rastreio CCR (50 anos para risco médio), sintomas (sangramento, mudança hábito), vigilância pós-polipectomia.\n**Intervalo pós-polipectomia:**\n- Pólipo hiperplástico pequeno: 10 anos\n- 1-2 adenomas tubulares <10mm: 5-10 anos\n- 3-4 adenomas OU adenoma 10-19mm: 3 anos\n- Adenoma ≥20mm OU adenoma viloso OU displasia de alto grau: 1 ano\n- ≥5 adenomas: 1 ano\n**PAF (Polipose Adenomatosa Familiar):** colonoscopia anual a partir dos 10-15 anos.", category: "gastroenterologia", tags: ["colonoscopia", "pólipo", "ccr", "vigilância"] },
  { id: "fc-gastro-009", front: "Como manejar o sangramento varicoso agudo em cirrótico?", back: "**Ressuscitação:** não hipervascular — transfundir para Hb 7-8g/dL (excesso piora pressão portal).\n**Vasoconstritor:** terlipressina 2mg IV 4/4h (ou somatostatina/octreotida) — iniciar IMEDIATAMENTE (mesmo antes da endoscopia).\n**ATB profilático:** ceftriaxona 1g/dia IV por 7 dias (reduz mortalidade).\n**Endoscopia:** ligadura elástica < 12h.\n**TIPS:** indicado se sangramento refratário ou como prevenção secundária precoce em Child C ou B com sangramento ativo.\n**Profilaxia secundária:** propranolol + ligadura elástica.", category: "gastroenterologia", tags: ["varizes", "sangramento", "terlipressina", "ligadura"] },
  { id: "fc-gastro-010", front: "Quais são os critérios de diagnóstico e tratamento da Doença do Refluxo Gastroesofágico (DRGE)?", back: "**Diagnóstico clínico:** pirose e/ou regurgitação ≥2×/semana por ≥4-8 semanas; se típico → sem endoscopia inicial.\n**Endoscopia:** indicada se: alarme (disfagia, perda de peso, anemia), idade >45 anos, sintomas > 5 anos (rastrear Esôfago de Barrett).\n**Esôfago de Barrett:** metaplasia intestinal → vigilância com biópsia (4 quadrantes a cada 2cm).\n**Tratamento:** IBP 1× ao dia 30min antes do café da manhã por 4-8 semanas; elevação decúbito; modificações de dieta.\n**Cirurgia (Nissen):** DRGE refratária com refluxo confirmado por pHmetria.", category: "gastroenterologia", tags: ["drge", "refluxo", "ibp", "barrett"] },
  { id: "fc-gastro-011", front: "Quais são os critérios de Child-Pugh e o que cada componente avalia?", back: "| Parâmetro | 1 pt | 2 pt | 3 pt |\n|---|---|---|---|\n| Bilirrubina (mg/dL) | <2 | 2-3 | >3 |\n| Albumina (g/dL) | >3,5 | 2,8-3,5 | <2,8 |\n| INR | <1,7 | 1,7-2,3 | >2,3 |\n| Ascite | Ausente | Leve-mod | Tensa |\n| Encefalopatia | Ausente | Grau 1-2 | Grau 3-4 |\n**Classificação:** A=5-6 pts (compensada, mortalidade perioperatória 5%), B=7-9 pts (15%), C=10-15 pts (>40%).", category: "gastroenterologia", tags: ["child-pugh", "cirrose", "prognóstico"] },
  { id: "fc-gastro-012", front: "Como diagnosticar e tratar a encefalopatia hepática de forma estruturada?", back: "**Graus (West Haven):** I = alteração sutil; II = desorientação + asterixis; III = confusão grave; IV = coma.\n**Precipitantes (6P):** Parasangramento GI, Proteína excessiva, Psicoativos (BZD, opioides), PBE, Purgação/constipação, Procedimento (shunt).\n**Tratamento:**\n1. Identificar e tratar precipitante\n2. Lactulose 30-45mL 4/4h (meta: 2-4 evacuações pastosas/dia)\n3. Rifaximina 550mg 12/12h (profilaxia de recorrência)\n4. Albumina se PBE\n5. NÃO restringir proteína (catabolismo piora).", category: "gastroenterologia", tags: ["encefalopatia", "hepática", "lactulose", "west haven"] },

  // ════════════════════════════════════════════════════════════════
  // HEMATOLOGIA — de 9 para ~70 (+61)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-hema-001", front: "Quais são os critérios diagnósticos da anemia e sua classificação morfológica?", back: "**Definição OMS:** Hb < 13g/dL (homens), < 12g/dL (mulheres), < 11g/dL (gestantes/crianças 6-60m).\n**Classificação por VCM:**\n- Microcítica (VCM < 80fL): deficiência de ferro, talassemia, anemia de doença crônica (alguns), sideroblástica\n- Normocítica (80-100fL): anemia de doença crônica, hemolítica, aplástica, insuficiência renal\n- Macrocítica (VCM > 100fL): deficiência B12/folato, hipotireoidismo, hepatopatia, medicamentos (metotrexato, AZT)\n**Reticulócitos:** elevados (hemolítica/sangramento) vs baixos (central).", category: "hematologia", tags: ["anemia", "classificação", "vcm"] },
  { id: "fc-hema-002", front: "Como diagnosticar e tratar a deficiência de ferro?", back: "**Investigação:** ferritina (< 30 ng/mL = deficiência; < 12 = depleção total), saturação de transferrina < 20%, ferro sérico baixo, TIBC elevado.\n**Atenção:** ferritina é reactante de fase aguda — pode estar falsamente normal em inflamação.\n**Causas:** sangramento GI (homens/pós-menopáusicas → colonoscopia), menorragia, má absorção (doença celíaca, gastrectomia).\n**Tratamento:** sulfato ferroso 200mg 3×/dia (intervalo 2h de alimentos, vitamina C melhora absorção) por 3-6 meses após normalização.\n**Ferro IV:** intolerância VO, má absorção, anemia grave pré-cirurgia, DRC.", category: "hematologia", tags: ["ferropenia", "ferro", "ferritina"] },
  { id: "fc-hema-003", front: "Quais são os critérios diagnósticos e o tratamento da PTI (Púrpura Trombocitopênica Imune)?", back: "**Diagnóstico de exclusão:** plaquetas < 100.000 sem outra causa identificável (excluir pseudotrombocitopenia, HIV, HCV, H. pylori, LES, drogas).\n**Tratamento (agudo):**\n- Plaquetas 20-50k sem sangramento: observar\n- Plaquetas < 20k OU sangramento: prednisona 1mg/kg/dia\n- Grave/refratário: IVIG 1g/kg/dia × 2 + dexametasona 40mg/dia × 4\n- Emergência hemorrágica: IVIG + corticoide + transfusão plaquetária (apenas se sangramento com risco de vida)\n**Refratária:** romiplostim, eltrombopag (agonistas de TPO), rituximabe, esplenectomia.", category: "hematologia", tags: ["pti", "plaquetas", "imune"] },
  { id: "fc-hema-004", front: "Como diferenciar as principais coagulopatias pelos exames laboratoriais?", back: "| Coagulopatia | TP/RNI | TTPa | Plaquetas |\n|---|---|---|---|\n| Deficiência de vitamina K / varfarina | ↑↑ | ↑ (leve) | Normal |\n| Hemofilia A/B | Normal | ↑↑ | Normal |\n| CIVD | ↑ | ↑ | ↓↓ |\n| DvW tipo 1 | Normal | ↑ (leve) | Normal |\n| PTI | Normal | Normal | ↓↓ |\n| Hepatopatia grave | ↑ | ↑ | ↓ |\n**Fibrinogênio:** baixo em CIVD e hepatopatia grave; D-dímero elevado em CIVD.", category: "hematologia", tags: ["coagulopatia", "tp", "ttpa", "civd"] },
  { id: "fc-hema-005", front: "Quais são as características e o manejo da crise vaso-oclusiva na doença falciforme?", back: "**Fisiopatologia:** polimerização da HbS em hipóxia/desidratação → isquemia tecidual → dor intensa.\n**Manejo da crise álgica:**\n1. Hidratação: 1,5× manutenção (SF 0,9% ou RL)\n2. Analgesia escalonada: dipirona/AINE → opioide fraco (tramadol) → opioide forte (morfina 0,1mg/kg IV, titulado)\n3. O₂ apenas se SpO₂ < 95%\n4. Calor local\n**Síndrome torácica aguda (STA):** infiltrado + dor torácica + febre → emergência → O₂, ATB (ceftriaxona + azitromicina), considerar exsanguineotransfusão.\n**Profilaxia:** hidroxiureia, penicilina V, vacinas.", category: "hematologia", tags: ["falciforme", "vaso-oclusiva", "dor", "hidroxiureia"] },
  { id: "fc-hema-006", front: "Quais são os critérios diagnósticos para Leucemia Mieloide Aguda (LMA) e como diferenciar das MDS?", back: "**LMA:** blastos ≥ 20% na medula óssea (WHO 2022) OU certas translocações independente da % de blastos (t(8;21), inv(16), t(15;17) = LMA-M3).\n**LMA-M3 (promielocítica):** urgência hematológica — CIVD proeminente, tratar com ATRA imediatamente ao diagnóstico.\n**MDS (Síndromes Mielodisplásticas):** citopenias + displasia + blastos < 20%.\n**Classificação WHO 2022:** incorpora mutações genéticas (FLT3, NPM1, IDH1/2, TP53) para prognóstico e escolha terapêutica.\n**Tratamento LMA padrão:** daunorrubicina + citarabina ('7+3').", category: "hematologia", tags: ["lma", "leucemia", "blastos", "atra"] },
  { id: "fc-hema-007", front: "Como estadiar e tratar o Linfoma de Hodgkin?", back: "**Estadiamento Ann Arbor:**\n- I: 1 região linfonodal\n- II: ≥2 regiões, mesmo lado do diafragma\n- III: ambos os lados do diafragma\n- IV: disseminado (fígado, MO)\n**Sufixos:** A = sem sintomas B; B = febre, sudorese noturna, perda de peso >10%\n**Histologia mais comum:** esclerose nodular (70%).\n**Tratamento:**\n- Estádio I-II favorável: ABVD × 2-4 ciclos + RT\n- Estádio I-II desfavorável/III-IV: ABVD × 6 ciclos ± RT\n- Refratário/recidivado: auto-TMO\n**Cura:** >80% nos estádios iniciais.", category: "hematologia", tags: ["hodgkin", "linfoma", "abvd", "ann arbor"] },
  { id: "fc-hema-008", front: "Quais as indicações e limites seguros para transfusão de hemocomponentes?", back: "**Concentrado de Hemácias (CH):**\n- Restrição: Hb <7g/dL (clinicamente estável); <8g/dL (cardiopata, pós-op, sangramento ativo)\n- Liberal vs restritivo: TRICC trial — restritivo (Hb 7) seguro em UTI geral\n**Plaquetas:**\n- Profilática: <10.000 (estável); <20.000 (febre/procedimento); <50.000 (procedimento invasivo); <100.000 (neurocirurgia)\n**Plasma (PFC):**\n- INR >1,5 com sangramento ativo ou procedimento; CIVD\n**Crioprecipitado:** fibrinogênio <150mg/dL + sangramento; hipofibrinogenemia congênita.", category: "hematologia", tags: ["transfusão", "hemácias", "plaquetas", "plasma"] },
  { id: "fc-hema-009", front: "Como reconhecer e manejar a Púrpura Trombótica Trombocitopênica (PTT)?", back: "**Pêntada clássica (nem sempre completa):** microangiopatia hemolítica (MAHA) + trombocitopenia + febre + neurológico + renal.\n**Diagnóstico prático:** MAHA + trombocitopenia sem outra causa → suspeitar PTT → ADAMTS13 < 10% confirma.\n**EMERGÊNCIA:** mortalidade > 90% sem tratamento.\n**Tratamento imediato:** plasmaférese (plasma fresco) — iniciar em < 4-8h da suspeita.\n**Não dar plaquetas** (piora trombose microvascular).\n**Imunossupressão:** corticoide + rituximabe (PTT imune).\n**SHU:** sem comprometimento neurológico, mais renal — eculizumabe no SHU atípico.", category: "hematologia", tags: ["ptt", "maha", "plasmaférese", "adamts13"] },
  { id: "fc-hema-010", front: "Quais são os principais efeitos adversos da quimioterapia e como manejá-los?", back: "**Neutropenia febril:** febre + neutrófilos < 500 → coletar hemoculturas → piperacilina-tazobactam IV imediato; MASCC score para estratificar alta ambulatorial.\n**Náuseas/vômitos:** ondansetrona + dexametasona + aprepitanto (para QT altamente emetizante).\n**Mucosite:** higiene oral, analgesia, glutamina tópica; grau 4 → nutrição parenteral.\n**Cardiotoxicidade por antraciclinas (doxorrubicina):** dose cumulativa → monitorar FEVE.\n**Nefrotoxicidade por cisplatina:** hiperhidratação pré e pós + amifostina.\n**Síndrome de lise tumoral:** hidratação + alopurinol/rasburicase + monitorar K+/fósforo/ácido úrico.", category: "hematologia", tags: ["quimioterapia", "neutropenia", "lise tumoral", "efeitos adversos"] },

  // ════════════════════════════════════════════════════════════════
  // OBSTETRÍCIA — de 8 para ~70 (+62)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-obst-001", front: "Quais são os critérios diagnósticos de pré-eclâmpsia e como classificar a gravidade?", back: "**Definição:** PA ≥ 140/90 mmHg em 2 aferições com intervalo ≥4h, após 20 semanas, em gestante previamente normotensa + proteinúria ≥ 300mg/24h (OU razão prot/creat ≥ 0,3 OU proteinúria 1+ na fita).\n**Com sinais de gravidade (qualquer um):** PA ≥ 160/110, creatinina ≥ 1,1, PLT < 100.000, TGO/TGP > 2× LSN, dor epigástrica, cefaleia grave, edema pulmonar, sintomas visuais.\n**Eclâmpsia:** convulsão tônico-clônica em pré-eclâmptica.\n**HELLP:** Hemólise + ELevação enzimas hepáticas + Low Platelets.", category: "obstetricia", tags: ["pré-eclâmpsia", "eclâmpsia", "hellp", "pa"] },
  { id: "fc-obst-002", front: "Como manejar a eclâmpsia na emergência?", back: "**ABC e posição lateral esquerda** (evitar compressão da VCI).\n**Sulfato de Magnésio (MgSO₄):**\n- Ataque: 4-6g IV em 15-20 min\n- Manutenção: 1-2g/h BIC\n- Antídoto da toxicidade: gluconato de cálcio 1g IV (10mL de 10%)\n- Monitorar: diurese ≥ 25mL/h, reflexo patelar presente, FR ≥ 12\n**Anti-hipertensivo de emergência:** hidralazina 5mg IV (repetir em 20min) OU labetalol 20mg IV OU nifedipina 10mg VO.\n**Meta:** PA < 160/110 (não normalizar rapidamente — risco de isquemia uteroplacentária).\n**Parto:** definir após estabilização materna.", category: "obstetricia", tags: ["eclâmpsia", "magnésio", "emergência", "convulsão"] },
  { id: "fc-obst-003", front: "Qual o diagnóstico diferencial de sangramento na primeira metade da gestação?", back: "**Com dor (emergências):**\n- Gravidez ectópica: dor + beta-hCG + saco gestacional fora do útero (rastreio com USTV)\n- Abortamento em curso: colo aberto + sangramento\n**Sem dor:**\n- Ameaça de abortamento: sangramento + colo fechado + BCF presente\n- Abortamento inevitável: colo aberto + BCF presente\n- Abortamento retido: colo fechado + sem BCF\n- Mola hidatiforme: sangramento + beta-hCG muito elevado + imagem em 'flocos de neve'\n**Beta-hCG + USTV = combinação diagnóstica essencial na 1ª metade.**", category: "obstetricia", tags: ["sangramento", "ectópica", "abortamento", "primeiro trimestre"] },
  { id: "fc-obst-004", front: "Quais são as indicações absolutas de cesariana?", back: "**Absolutas:**\n1. Placenta prévia oclusiva total\n2. Situação transversa com membranas rotas\n3. Prolapso de cordão umbilical\n4. Apresentação pélvica com desproporção céfalo-pélvica\n5. 2 ou mais cesarianas anteriores (relativa — pode tentar parto vaginal VBAC)\n6. Herpes genital ativo no trabalho de parto\n7. Vasa prévia\n8. Sofrimento fetal agudo sem condições de parto vaginal imediato\n9. Descolamento prematuro de placenta com instabilidade materna\n**OBS:** diabetes e hipertensão NÃO são indicações absolutas.", category: "obstetricia", tags: ["cesariana", "indicações", "parto"] },
  { id: "fc-obst-005", front: "Como diagnosticar e manejar a hemorragia pós-parto (HPP)?", back: "**Definição:** perda sanguínea > 500mL (parto normal) ou > 1000mL (cesariana) ou qualquer perda com instabilidade hemodinâmica.\n**Causas (4T):** Tônus (atonia = 80%), Trauma (laceração), Tecido (restos placentários), Trombina (coagulopatia).\n**Manejo ATÔNIA:**\n1. Ocitocina 10UI IM/IV bolus lento → 20UI BIC\n2. Misoprostol 800mcg sublingual/retal\n3. Metilergometrina 0,2mg IM (contraindicado em HAS)\n4. Ácido tranexâmico 1g IV em < 3h\n5. Compressão bimanual uterina\n6. Balão de Bakri, B-Lynch, histerectomia se refratário.", category: "obstetricia", tags: ["hemorragia", "hpp", "atonia", "ocitocina"] },
  { id: "fc-obst-006", front: "Quais são os critérios diagnósticos e conduta no diabetes gestacional?", back: "**Rastreio:** glicemia de jejum na 1ª consulta pré-natal.\n**Diagnóstico GJ:**\n- ≥ 126mg/dL na 1ª consulta = DM pré-gestacional\n- 92-125mg/dL = DM gestacional (sem necessidade de TOTG)\n- < 92mg/dL → TOTG 75g com 24-28 semanas\n**TOTG (ADA/OMS):** GJ ≥92 OU 1h ≥180 OU 2h ≥153 = DM gestacional (basta UM critério).\n**Tratamento:** dieta + atividade física → se GJ > 95 ou 2hpós > 120 → insulina (metformina é alternativa mas atravessa placenta).\n**Meta:** GJ < 95, 1h pós-prandial < 140, 2h pós-prandial < 120.", category: "obstetricia", tags: ["diabetes", "gestacional", "totg", "insulina"] },
  { id: "fc-obst-007", front: "Como identificar e manejar o trabalho de parto prematuro (TPP)?", back: "**Diagnóstico:** contrações regulares ≥4/20min + modificação cervical entre 20-36+6 semanas.\n**Tratamento:**\n1. Corticoide para maturidade pulmonar fetal: betametasona 12mg IM 24/24h × 2 doses (24-34+6 semanas; considerar 34-36+6)\n2. Neuroproteção fetal: MgSO₄ 4g IV + 1g/h BIC (< 32 semanas, reduz paralisia cerebral)\n3. Tocolítico (ganhar 48h para corticoide): nifedipina 10mg VO/20min × 3 doses → 20mg VO 8/8h\n4. ATB apenas se RPMO (ruptura prematura membranas)\n**Marcadores de risco:** fibronectina fetal + cervicometria < 25mm.", category: "obstetricia", tags: ["prematuro", "tpp", "corticoide", "betametasona"] },
  { id: "fc-obst-008", front: "Quais são os critérios para diagnóstico e tratamento da incompatibilidade Rh?", back: "**Fisiopatologia:** mãe Rh- sensibilizada → anticorpos anti-D atravessam placenta → hemólise fetal → hidropsia fetal.\n**Prevenção:** imunoglobulina anti-D (RhoGAM) 300mcg IM na 28ª semana E em até 72h de qualquer evento sensibilizante (parto, abortamento, amniocentese, trauma abdominal) em gestantes Rh-.\n**Monitoramento:** se mãe já sensibilizada (Coombs indireto +) → titulação de anticorpos + dopplervelocimetria da artéria cerebral média fetal.\n**ACM > 1,5 MoM:** indica anemia fetal grave → transfusão intravascular (cordocentese).", category: "obstetricia", tags: ["rh", "incompatibilidade", "rhogam", "hemolítica"] },

  // ════════════════════════════════════════════════════════════════
  // PEDIATRIA — de 11 para ~70 (+59)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-ped-001", front: "Quais são os marcos do desenvolvimento neuropsicomotor (DNPM) que devem ser rastreados?", back: "**2 meses:** sorriso social, sustentação parcial da cabeça.\n**4 meses:** sustenta a cabeça, segura objetos.\n**6 meses:** senta com apoio, balbucia.\n**9 meses:** senta sem apoio, transfere objetos, 'mama/papa' inespecífico.\n**12 meses:** fica de pé com apoio, 'mama/papa' específico, pinça.\n**18 meses:** caminha, 10-15 palavras, aponta.\n**24 meses:** sobe/desce escadas, 2 palavras juntas, nomeia partes do corpo.\n**Red flags para encaminhar:** não sorri aos 2m, não sustenta cabeça aos 4m, não senta aos 9m, não anda aos 18m, regressão em qualquer fase.", category: "pediatria", tags: ["dnpm", "desenvolvimento", "marcos"] },
  { id: "fc-ped-002", front: "Como calcular e interpretar o Escore de Apgar?", back: "| Sinal | 0 | 1 | 2 |\n|---|---|---|---|\n| Frequência Cardíaca | Ausente | <100 | ≥100 |\n| Respiração | Ausente | Irregular | Regular/choro |\n| Tônus muscular | Flácido | Alguma flexão | Ativo |\n| Irritabilidade reflexa | Sem resposta | Careta | Choro vigoroso |\n| Cor | Azul/pálido | Acrocianose | Rosado |\n\n**Interpretação:** 7-10 = normal; 4-6 = depressão moderada; 0-3 = depressão grave.\n**Timing:** 1 e 5 minutos (repetir a cada 5min se < 7 até 20 min).\n**Apgar NÃO decide reanimação** — décision clínica antes do 1º minuto.", category: "pediatria", tags: ["apgar", "neonato", "reanimação"] },
  { id: "fc-ped-003", front: "Como calcular a hidratação de manutenção em crianças (fórmula de Holliday-Segar)?", back: "**Fórmula de Holliday-Segar:**\n- Primeiros 10kg: 100mL/kg/dia (ou 4mL/kg/h)\n- 10-20kg: +50mL/kg/dia pelos kg nessa faixa (ou +2mL/kg/h)\n- >20kg: +20mL/kg/dia pelos kg acima de 20 (ou +1mL/kg/h)\n\n**Exemplo (30kg):** 1000 + 500 + 200 = 1700mL/dia ou ~71mL/h\n\n**Atenção:** esta fórmula foi desenvolvida para manutenção — não usar para reposição de déficit ou perdas anormais.\n**Solução padrão em pediátria:** SG5% + NaCl 0,225% (¼ de soro fisiológico) + KCl 20mEq/L.", category: "pediatria", tags: ["hidratação", "holliday-segar", "manutenção"] },
  { id: "fc-ped-004", front: "Quais são os critérios da OMS para desnutrição aguda grave em crianças e como tratar?", back: "**Critérios (qualquer um):** Peso/Estatura < -3DP (magreza grave) OU MUAC < 115mm (6-59 meses) OU edema bilateral (kwashiorkor).\n**Fases do tratamento (OMS):**\n- Fase 1 (estabilização, 1-7 dias): tratar hipoglicemia, hipotermia, desidratação, infecções; F75 (75kcal/100mL)\n- Fase de transição (7-14 dias): F100 (100kcal/100mL)\n- Fase 2 (reabilitação): F100 ou ATPU (alimento terapêutico pronto para uso)\n**Perigo:** síndrome de realimentação — não aumentar kcal rápido no início.\n**SUA (DAG sem complicações):** tratamento ambulatorial com ATPU.", category: "pediatria", tags: ["desnutrição", "kwashiorkor", "oms", "atpu"] },
  { id: "fc-ped-005", front: "Como manejar a desidratação em crianças pela classificação da OMS?", back: "**Sem desidratação:** TRO preventiva — oferecer líquidos em casa (plano A).\n**Desidratação (2 ou mais sinais — olhos fundos, turgor diminuído, bebe avidamente, inquieto):** TRO 50-100mL/kg em 4h (plano B); se falha → soro IV.\n**Desidratação grave (2+ sinais — incapaz de beber, turgor muito ruim, olhos muito fundos, letárgico):** Ringer Lactato 100mL/kg IV:\n- Lactente (<12m): 30mL/kg em 1h → 70mL/kg em 5h\n- Criança (>12m): 30mL/kg em 30min → 70mL/kg em 2,5h\n**Reavaliação:** obrigatória a cada fase.", category: "pediatria", tags: ["desidratação", "tro", "hidratação", "oms"] },
  { id: "fc-ped-006", front: "Quais são os critérios de internação para bronquiolite viral aguda em lactentes?", back: "**Internação (qualquer critério):**\n- SpO₂ < 90-92% em AA\n- Apneia ou risco de apneia (< 3 meses ou prematuro)\n- FR > 70ipm ou dificuldade grave de alimentação\n- Sinais de dificuldade respiratória moderada-grave (Wang ≥ 9)\n- Criança de alto risco: cardiopatia congênita, displasia broncopulmonar, imunodeficiência\n**UTI:** apneia recorrente, falência respiratória, SpO₂ < 85% com O₂\n**NÃO usar de rotina:** broncodilatador (não há evidência), corticoide sistêmico, ATB, adrenalina inalada.", category: "pediatria", tags: ["bronquiolite", "internação", "vsr", "lactente"] },
  { id: "fc-ped-007", front: "Como calcular a dose de adrenalina e desfibrilação no PALS?", back: "**Adrenalina na PCR pediátrica:**\n- Dose: 0,01 mg/kg IV/IO (máximo 1mg)\n- Solução 1:10.000 (0,1mg/mL): 0,1mL/kg\n- Repetir a cada 3-5 minutos\n**Desfibrilação:**\n- 1ª dose: 2 J/kg (bifásico)\n- 2ª dose: 4 J/kg\n- Doses subsequentes: 4-10 J/kg (máximo 200J)\n**Amiodarona para FV/TV refratária:** 5mg/kg IV/IO bolus após 3ª desfibrilação.\n**Sequência:** RCP 2min → ritmo → choque (se FV/TV) → RCP 2min → ritmo → adrenalina + amiodarona.", category: "pediatria", tags: ["pals", "adrenalina", "desfibrilação", "pcr pediátrica"] },
  { id: "fc-ped-008", front: "Quais são os critérios diagnósticos da Doença de Kawasaki e por que é urgente tratar?", back: "**Critérios (febre ≥ 5 dias + ≥4 dos 5):**\n1. Conjuntivite bilateral não purulenta\n2. Alterações de boca: lábios secos/gretados, língua em framboesa, eritema orofaríngeo\n3. Exantema polimorfo\n4. Alterações de extremidades: eritema/edema palmas e plantas → descamação\n5. Adenopatia cervical unilateral > 1,5cm\n**Urgência:** aneurismas de coronárias em 15-25% sem tratamento → IAM em criança.\n**Tratamento:** IVIG 2g/kg dose única + AAS 80-100mg/kg/dia (fase aguda) → 3-5mg/kg/dia (manutenção).\n**Kawasaki incompleto:** <4 critérios mas com aneurisma — ecocardiograma obrigatório.", category: "pediatria", tags: ["kawasaki", "coronária", "ivig", "criança"] },
  { id: "fc-ped-009", front: "Como diagnosticar e tratar a otite média aguda (OMA) em crianças?", back: "**Diagnóstico:** início agudo de sintomas + sinais de inflamação de MT (eritema, abaulamento, opacificação) + efusão no ouvido médio.\n**Quando tratar com ATB:**\n- Sempre: < 6 meses, OMA bilateral em < 2 anos, OMA com otorreia, grave (febre ≥ 39°C ou dor intensa)\n- Observar 48-72h (leve, unilateral, ≥ 2 anos): watchful waiting\n**Antibiótico:** amoxicilina 50mg/kg/dia 8/8h por 5-7 dias (10 dias se < 2 anos).\n**Falha em 48-72h:** amoxicilina-clavulanato 90mg/kg/dia.\n**OMA recorrente:** ≥ 3 episódios/6 meses → tubos de ventilação.", category: "pediatria", tags: ["otite", "oma", "amoxicilina", "criança"] },
  { id: "fc-ped-010", front: "Quais são os sinais de alerta para meningite bacteriana em crianças e o manejo inicial?", back: "**Sinais clássicos (podem estar ausentes em < 18 meses):** febre + rigidez de nuca + petéquias/púrpura (sinal de meningococcemia!).\n**Em lactentes:** fontanela abaulada + irritabilidade paradoxal + choro agudo.\n**ATB IMEDIATO** (não aguardar LCR se instável):\n- Ceftriaxona 100mg/kg/dia IV 12/12h\n- Dexametasona 0,15mg/kg/dose 6/6h × 4 dias (antes ou com 1ª dose ATB — reduz sequelas auditivas em S. pneumoniae)\n**LCR:** proteína elevada, glicose baixa, leucocitose PMN, Gram, cultura.\n**Meningococcemia:** petéquias + púrpura + instabilidade = emergência máxima → penicilina G 300.000UI/kg/dia.", category: "pediatria", tags: ["meningite", "pediatria", "ceftriaxona", "meningococcemia"] },
  { id: "fc-ped-011", front: "Como manejar a febre em crianças — quando tratar e quais os antitérmicos de escolha?", back: "**Definição:** temperatura retal ≥ 38°C.\n**Quando tratar:** discomfort (não para 'prevenir convulsão febril').\n**Antitérmicos:**\n- Paracetamol: 10-15mg/kg/dose VO/retal, 4/4h-6/6h (máx 5 doses/dia; máx 75mg/kg/dia)\n- Ibuprofeno: 5-10mg/kg/dose VO, 6/6h-8/8h (≥ 6 meses; contraindicado em varicela e dengue)\n**NÃO usar AAS em < 12 anos** (Síndrome de Reye).\n**Febre sem foco em < 3 meses:** hospitalizar e investigar (sepse neonatal tardia).\n**Febre na neutropenia:** emergência — culturas + pip-tazo imediato.", category: "pediatria", tags: ["febre", "paracetamol", "ibuprofeno", "criança"] },
  { id: "fc-ped-012", front: "Quais são os critérios do Calendário Nacional de Vacinação para as vacinas essenciais nos primeiros 2 anos?", back: "**Nascimento:** BCG + HB (hepatite B).\n**2 meses:** Penta (DTP+Hib+HB) + VIP (pólio inativada) + VRH (rotavírus) + PCV10.\n**3 meses:** Penta + VIP + Meningocócica C.\n**4 meses:** Penta + VIP + VRH + PCV10.\n**5 meses:** Penta + VIP + Meningocócica C.\n**6 meses:** Influenza (anual).\n**9 meses:** FA (febre amarela) + Sarampo (dose zero).\n**12 meses:** SCR (sarampo/caxumba/rubéola) + VZ (varicela) + PCV10 reforço + Meningocócica C reforço.\n**15 meses:** SCR 2ª dose + VZ 2ª dose + DTP reforço + VOP (pólio oral) + Hepatite A.", category: "pediatria", tags: ["vacina", "calendário", "imunização"] },

  // ════════════════════════════════════════════════════════════════
  // EMERGÊNCIA — de 17 para ~70 (+53)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-em-001", front: "Quais são as causas reversíveis de PCR (5H e 5T) e como lembrar?", back: "**5H:**\n- Hipovolemia → SF/sangue\n- Hipóxia → O₂/IOT\n- Hidrogênio (acidose) → bicarbonato\n- Hipo/Hipercalemia → tratar eletrólitos\n- Hipotermia → reaquecimento\n\n**5T:**\n- Tensão (pneumotórax hipertensivo) → descompressão\n- Tamponamento cardíaco → pericardiocentese\n- Toxinas → antídoto\n- Trombose pulmonar (TEP) → trombólise\n- Trombose coronariana (IAM) → cateterismo\n\nMemorizar: H's e T's garantem a sobrevivência quando a PCR tem causa tratável.", category: "emergencia", tags: ["pcr", "5h5t", "causas reversíveis"] },
  { id: "fc-em-002", front: "Qual a sequência correta do ACLS para FV/TV sem pulso?", back: "1. Confirmar ausência de pulso e ritmo chocável\n2. **Desfibrilação** imediata: 200J bifásico\n3. **RCP 2 minutos** (compressões 100-120/min, profundidade 5-6cm, razão 30:2)\n4. Verificar ritmo → FV/TV → 2° choque 200-300J\n5. RCP 2 min + **Adrenalina 1mg IV** (repetir 3-5min)\n6. Verificar ritmo → 3° choque 360J\n7. **Amiodarona 300mg IV** (ou lidocaína 1-1,5mg/kg)\n8. Continuar ciclos: RCP → ritmo → choque → adrenalina (3-5min)\n\n**Minimizar interrupções nas compressões** — cada 10s sem compressão reduz sobrevida.", category: "emergencia", tags: ["acls", "fv", "desfibrilação", "adrenalina"] },
  { id: "fc-em-003", front: "Como calcular e usar o SOFA score na sepse?", back: "**SOFA (Sequential Organ Failure Assessment):** avalia 6 sistemas (0-4 pts cada = máximo 24).\n| Sistema | Parâmetro |\n|---|---|\n| Respiratório | PaO₂/FiO₂ |\n| Coagulação | Plaquetas |\n| Hepático | Bilirrubina |\n| Cardiovascular | PAM/vasopressor |\n| Neurológico | GCS |\n| Renal | Creatinina/diurese |\n\n**Sepse:** suspeita de infecção + SOFA ≥ 2 pontos (ou aumento ≥ 2 do basal).\n**qSOFA (triagem):** FR ≥ 22 + alteração mental + PA ≤ 100 (≥ 2 = alto risco → calcular SOFA).\n**Choque séptico:** sepse + vasopressor para PAM ≥ 65 + lactato > 2mmol/L.", category: "emergencia", tags: ["sofa", "sepse", "qsofa", "choque"] },
  { id: "fc-em-004", front: "Quais são os critérios de SIRS e como diferem dos critérios atuais de sepse?", back: "**SIRS (critérios antigos, Sepsis-1/2):**\n2 ou mais: T° >38°C ou <36°C; FC >90; FR >20 ou PaCO₂ <32; Leucócitos >12k ou <4k ou >10% bastões.\n\n**Por que foram abandonados para sepse:**\n- Muito inespecíficos (cirurgia, trauma, pancreatite causam SIRS sem infecção)\n- Pouca capacidade discriminativa para mortalidade\n\n**Critérios atuais Sepsis-3 (2016):**\n- Sepse = infecção + disfunção orgânica (SOFA ≥ 2)\n- Muito mais específico para mortalidade e necessidade de UTI\n\n**SIRS ainda tem valor** em triagem pré-hospitalar e pediatria (Phoenix Score).", category: "emergencia", tags: ["sirs", "sepse", "sepsis-3", "histórico"] },
  { id: "fc-em-005", front: "Qual o manejo da via aérea difícil antecipada vs inesperada?", back: "**Antecipada (LEMON):** L=Look externamente; E=Evaluate 3-3-2; M=Mallampati; O=Obstruction; N=Neck mobility.\n**Estratégia para VAD antecipada:**\n1. Intubação acordado com fibroscópio (padrão-ouro se cooperativo)\n2. Videolaringoscópio (C-MAC, McGrath) — aumenta visibilização 1-2 graus Cormack\n**VAD inesperada (falhou IOT):**\n1. Chamar ajuda + máscara facial\n2. Dispositivo supraglótico (LMA, iGel)\n3. Videolaringoscópio\n4. **CICO (Can't Intubate Can't Oxygenate):** cricotireoidotomia cirúrgica imediata\n**Regra:** máximo 3 tentativas de laringoscopia antes de declarar falha.", category: "emergencia", tags: ["via aérea", "intubação", "cico", "cricotireoidotomia"] },
  { id: "fc-em-006", front: "Como diagnosticar e tratar o tromboembolismo pulmonar (TEP) na emergência?", back: "**Probabilidade pré-teste (Wells):** ≤4 = baixa; >4 = alta.\n**Investigação:** D-dímero (negativo exclui se prob. baixa/moderada); Angio-TC (padrão-ouro).\n**PERC rule** (todos os 8 critérios ausentes = sem investigação necessária em baixa probabilidade).\n**TEP alto risco (maciço):** hipotensão ou choque → trombólise sistêmica (alteplase 100mg IV em 2h).\n**TEP risco intermediário:** heparina + monitorização; trombólise se deterioração.\n**TEP baixo risco:** anticoagulação ambulatorial (DOAC — rivaroxabana ou apixabana).\n**Anticoagulação:** heparina 80UI/kg IV → 18UI/kg/h (TTPa 60-80s).", category: "emergencia", tags: ["tep", "embolia", "trombólise", "wells"] },
  { id: "fc-em-007", front: "Quais são os critérios de Toronto para alta de síncope na emergência?", back: "**Canadian Syncope Risk Score (preferível ao Toronto):**\n- ≤ 0: risco muito baixo → alta\n- 1-3: baixo → observar 2-6h\n- 4-7: intermediário → internação\n- ≥ 8: alto → internação urgente\n\n**Red flags que indicam internação independente:**\n- Síncope durante exercício\n- Síncope em decúbito\n- Precede palpitações\n- ECG anormal: QTc > 500ms, BRE novo, BAV 2°/3°, TV\n- Cardiopatia estrutural conhecida\n- Troponina elevada, BNP > 125\n\n**Vasovagal típico + ECG normal + exame normal + jovem:** alta segura.", category: "emergencia", tags: ["síncope", "canadian", "alta", "estratificação"] },
  { id: "fc-em-008", front: "Quais são os critérios de Beers para medicamentos potencialmente inapropriados em idosos na emergência?", back: "**Critérios de Beers (AGS 2023) — EVITAR em idosos ≥ 65 anos:**\n- Benzodiazepínicos (qualquer): risco de queda, delirium, dependência\n- Anti-histamínicos 1ª geração (difenidramina): anticolinérgicos → delirium\n- AINEs: sangramento GI, IRA, HAS\n- Amiodarona: 1ª linha para FA em idosos (preferir BB ou BCC)\n- Antipsicóticos em demência: risco de AVC e morte\n- Nitrofurantoína (ClCr < 30): neuropatia, pneumonite\n- Glibenclamida: hipoglicemia prolongada (preferir glipizida, glinidas)\n\n**STOPP/START:** ferramenta europeia complementar.", category: "emergencia", tags: ["beers", "idoso", "inapropriados", "geriatria"] },

  // ════════════════════════════════════════════════════════════════
  // GERIATRIA — de 18 para ~70 (+52)
  // ════════════════════════════════════════════════════════════════
  { id: "fc-geri-001", front: "O que são as síndromes geriátricas e quais os 5I da geriatria?", back: "Síndromes geriátricas: condições clínicas multifatoriais que não se encaixam nas doenças-órgão tradicionais, resultantes da interação entre vulnerabilidade do idoso e estressores.\n\n**5I (gigantes da geriatria):**\n1. **I**nstabilidade postural e quedas\n2. **I**mobilidade\n3. **I**ncontinência (urinária/fecal)\n4. **I**nsuficiência cognitiva (demência, delirium)\n5. **I**atrogenia (polifarmácia, reações adversas)\n\n**6° I** frequentemente adicionado: **I**nfecções (maior susceptibilidade e apresentação atípica).\n\nNão são inevitáveis do envelhecimento — são tratáveis e preveníveis.", category: "geriatria", tags: ["geriatria", "5i", "síndromes geriátricas"] },
  { id: "fc-geri-002", front: "Como avaliar fragilidade no idoso e qual a importância clínica?", back: "**Fenótipo de Fried (≥ 3 de 5 = frágil):**\n1. Perda de peso não intencional (>4,5kg/ano)\n2. Exaustão autorrelatada\n3. Força de preensão palmar reduzida\n4. Velocidade de marcha lenta\n5. Baixa atividade física\n\n**Pré-frágil:** 1-2 critérios.\n\n**Clinical Frailty Scale (CFS, 1-9):** mais simples e aplicável na emergência.\n\n**Importância:** frágil → maior risco de quedas, hospitalização, mortalidade, piora pós-cirurgia.\nImpacta decisão de: cirurgia, diálise, quimioterapia, UTI.\n\n**Intervenções:** exercício de resistência, suplementação proteica, revisão de polifarmácia.", category: "geriatria", tags: ["fragilidade", "fried", "cfs", "avaliação"] },
  { id: "fc-geri-003", front: "Como diferenciar delirium, demência e depressão no idoso (os 3D)?", back: "| Característica | Delirium | Demência | Depressão |\n|---|---|---|---|\n| Início | Agudo (horas-dias) | Insidioso (meses-anos) | Semanas-meses |\n| Consciência | Alterada, flutuante | Preservada inicialmente | Preservada |\n| Atenção | Muito comprometida | Comprometida tarde | Variável |\n| Memória | Comprometida (recente) | Comprometida (recente>remota) | Comprometida subjetivamente |\n| Curso | Flutuante | Progressivo | Persistente |\n| Reversível? | Sim (se causa tratada) | Geralmente não | Sim com tratamento |\n\n**CAM-ICU:** ferramenta de triagem de delirium em UTI.", category: "geriatria", tags: ["delirium", "demência", "depressão", "3d"] },
  { id: "fc-geri-004", front: "Quais são os fatores de risco para queda em idosos e como prevenir?", back: "**Fatores intrínsecos:** hipotensão ortostática, fraqueza muscular, distúrbio de marcha/equilíbrio, déficit visual, polifarmácia (especialmente BZD, anti-hipertensivos), neuropatia, demência.\n\n**Fatores extrínsecos:** iluminação, tapetes, calçados inadequados, banheiro sem barras.\n\n**Avaliação:** Timed Up and Go (TUG) > 12s = risco elevado; Berg Balance Scale.\n\n**Prevenção multicomponente:**\n- Exercício de equilíbrio e força (tai chi, musculação)\n- Revisão de medicamentos (retirar BZD)\n- Avaliação visual\n- Adaptação domiciliar\n- Vitamina D se deficiente (reduz risco de queda).", category: "geriatria", tags: ["queda", "idoso", "prevenção", "risco"] },
  { id: "fc-geri-005", front: "Quais são os critérios diagnósticos para Doença de Alzheimer e como estadiar?", back: "**Critérios NIA-AA 2011:** declínio cognitivo progressivo + impacto nas atividades de vida diária + não explicado por outra condição.\n**Biomarcadores:** amiloide PET ou LCR (Aβ42↓), tau PET ou LCR (p-tau↑), neurodegeneração (FDG-PET, atrofia hipocampal na RM).\n\n**CDR (Clinical Dementia Rating):**\n- 0 = normal; 0,5 = questionável; 1 = leve; 2 = moderado; 3 = grave.\n\n**Tratamento:**\n- Leve-moderado: inibidores de colinesterase (donepezila 5-10mg, rivastigmina)\n- Moderado-grave: adicionar memantina\n- Lecanemabe/donanemabe (anti-amiloide): novos — retardam progressão no estágio precoce.", category: "geriatria", tags: ["alzheimer", "demência", "cdr", "donepezila"] },
  { id: "fc-geri-006", front: "Como manejar a hipotensão ortostática em idosos?", back: "**Definição:** queda de PAS ≥ 20mmHg ou PAD ≥ 10mmHg em 3 minutos após ortostase.\n\n**Causas:** hipovolemia, medicamentos (anti-hipertensivos, diuréticos, alfa-bloqueadores, levodopa, ADT, antipsicóticos), neuropatia autonômica, Parkinson.\n\n**Sintomas:** tontura, pré-síncope, quedas, cefaleia occipital, visão turva.\n\n**Manejo:**\n1. Revisar e reduzir medicamentos causadores\n2. Aumentar ingesta de sódio e líquidos\n3. Meias de compressão\n4. Elevação da cabeceira do leito (30°)\n5. Movimentos lentos ao levantar\n6. Fludrocortisona 0,1-0,2mg/dia (2ª linha)\n7. Midodrina 2,5-10mg 2-3×/dia.", category: "geriatria", tags: ["hipotensão ortostática", "queda", "idoso", "medicamentos"] },
];
